const result = $input.first().json;
if (result.status !== 'completed') throw new Error('decision step did not complete');
if (!result.output?.reader_chapter) throw new Error('reader chapter missing');
if (!result.response_id || !result.model) throw new Error('Codex response metadata missing');
if (!result.decision_state?.steps?.step_09_spatial_layout) throw new Error('decision_state was not updated');
return [{ json: { passed: true, run_id: result.run_id, step: result.step_key, model: result.model, response_id: result.response_id } }];
